render_chart <- function(data, cfg, manifest) { wkt_col <- cfg$size %||% "wkt"; chart_validate_columns(data, list(region = cfg$x, value = cfg$y, wkt = wkt_col), c("region", "value", "wkt")); data$.mynx_region <- data[[cfg$x]]; data$.mynx_value <- data[[cfg$y]]; data$.mynx_wkt <- data[[wkt_col]]; shapes <- sf::st_as_sf(data, wkt = ".mynx_wkt", crs = 4326); p <- ggplot2::ggplot(shapes) + ggplot2::geom_sf(ggplot2::aes(fill = .mynx_value), colour = "white", linewidth = 0.3) + ggplot2::scale_fill_gradient(low = "#E2E8F0", high = cfg$color %||% "#0A84FF") + ggplot2::theme_void() + ggplot2::labs(title = cfg$title %||% NULL, fill = cfg$y); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
